import { useTheme as useEmotionTheme } from '@emotion/react';
import {
  StyledEngineProvider,
  THEME_ID,
  ThemeProvider,
  type Theme,
  type ThemeProviderProps,
} from '@mui/material/styles';
import { useMemo, type ReactNode } from 'react';
import { createSvTheme } from './create-theme';

const defaultTheme = createSvTheme({
  cssVariables: {
    cssVarPrefix: 'sv',
    colorSchemeSelector: 'data-mui-color-scheme',
  },
  colorSchemes: { light: true, dark: true },
});

export interface SvThemeProviderProps extends Omit<
  ThemeProviderProps<Theme>,
  'theme' | 'children'
> {
  children: ReactNode;
  theme?: Theme;
  /** Set false to use the application's existing Emotion insertion order. */
  injectFirst?: boolean;
  /** Create an independent mode context instead of inheriting the outer one. */
  disableNestedContext?: boolean | undefined;
  /** Skip variables already emitted by a parent using the same theme. */
  disableStyleSheetGeneration?: boolean | undefined;
  /** Recalculate raw theme values when the mode changes. CSS variables do not need this. */
  forceThemeRerender?: boolean | undefined;
  /** Element receiving the color-scheme selector; defaults to the document root. */
  colorSchemeNode?: Element | null | undefined;
}

export function SvThemeProvider({
  children,
  theme = defaultTheme,
  injectFirst = true,
  defaultMode = 'light',
  modeStorageKey = 'sv-mode',
  colorSchemeStorageKey = 'sv-color-scheme',
  ...props
}: SvThemeProviderProps) {
  const outerTheme = useEmotionTheme();
  const scoped = THEME_ID in outerTheme;
  // Preserve an existing MUI scope without introducing one for applications
  // whose nested ThemeProviders use ordinary, unscoped themes.
  const providerTheme = useMemo(
    () => (scoped ? { [THEME_ID]: theme } : theme),
    [scoped, theme]
  );
  return (
    <StyledEngineProvider injectFirst={injectFirst}>
      <ThemeProvider<typeof providerTheme>
        theme={providerTheme}
        defaultMode={defaultMode}
        modeStorageKey={modeStorageKey}
        colorSchemeStorageKey={colorSchemeStorageKey}
        {...props}
      >
        {children}
      </ThemeProvider>
    </StyledEngineProvider>
  );
}
